mutations.find:
if (options.dryRun) {
  printDryRun(plan, plan.enable, "write", context);
  return EXIT_OK;
}

mutations.replace:
if (options.dryRun) {
  for (const file of plan.files) {
    fs.mkdirSync(path.dirname(file.path), { recursive: true });
    fs.writeFileSync(file.path, file.text);
  }
  printDryRun(plan, plan.enable, "write", context);
  return EXIT_OK;
}
